Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'PRATINGRPRODCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &pratIngrProdCodigo1.FromString(&GridStateDynamicFilter.Value) If not &pratIngrProdCodigo1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterpratIngrProdCodigoDescription = format('%1 (%2)', "Produto", "=") EndCase &pratIngrProdCodigo = &pratIngrProdCodigo1 print printBlockFilterpratIngrProdCodigo EndIf Case &DynamicFiltersSelector1 = !'AREENSETAPANOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &AreEnsEtapaNome1.FromString(&GridStateDynamicFilter.Value) If not &AreEnsEtapaNome1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterAreEnsEtapaNomeDescription = format('%1 (%2)', "Etapa Nome ", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterAreEnsEtapaNomeDescription = format('%1 (%2)', "Etapa Nome ", "WWP_FilterContains") EndCase &AreEnsEtapaNome = &AreEnsEtapaNome1 print printBlockFilterAreEnsEtapaNome EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'PRATINGRPRODCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &pratIngrProdCodigo2.FromString(&GridStateDynamicFilter.Value) If not &pratIngrProdCodigo2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterpratIngrProdCodigoDescription = format('%1 (%2)', "Produto", "=") EndCase &pratIngrProdCodigo = &pratIngrProdCodigo2 print printBlockFilterpratIngrProdCodigo EndIf Case &DynamicFiltersSelector2 = !'AREENSETAPANOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &AreEnsEtapaNome2.FromString(&GridStateDynamicFilter.Value) If not &AreEnsEtapaNome2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterAreEnsEtapaNomeDescription = format('%1 (%2)', "Etapa Nome ", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterAreEnsEtapaNomeDescription = format('%1 (%2)', "Etapa Nome ", "WWP_FilterContains") EndCase &AreEnsEtapaNome = &AreEnsEtapaNome2 print printBlockFilterAreEnsEtapaNome EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'PRATINGRPRODCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &pratIngrProdCodigo3.FromString(&GridStateDynamicFilter.Value) If not &pratIngrProdCodigo3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterpratIngrProdCodigoDescription = format('%1 (%2)', "Produto", "=") EndCase &pratIngrProdCodigo = &pratIngrProdCodigo3 print printBlockFilterpratIngrProdCodigo EndIf Case &DynamicFiltersSelector3 = !'AREENSETAPANOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &AreEnsEtapaNome3.FromString(&GridStateDynamicFilter.Value) If not &AreEnsEtapaNome3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterAreEnsEtapaNomeDescription = format('%1 (%2)', "Etapa Nome ", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterAreEnsEtapaNomeDescription = format('%1 (%2)', "Etapa Nome ", "WWP_FilterContains") EndCase &AreEnsEtapaNome = &AreEnsEtapaNome3 print printBlockFilterAreEnsEtapaNome EndIf EndCase EndIf EndIf EndIf If not &TFpratIngrProdCodigo_Sel.IsEmpty() print printBlockTFpratIngrProdCodigo_Sel Else If not &TFpratIngrProdCodigo.IsEmpty() print printBlockTFpratIngrProdCodigo EndIf EndIf If not &TFAreEnsEtapaNome_Sel.IsEmpty() print printBlockTFAreEnsEtapaNome_Sel Else If not &TFAreEnsEtapaNome.IsEmpty() print printBlockTFAreEnsEtapaNome EndIf EndIf &TFcarGruTurno_Sels.FromJson(&TFcarGruTurno_SelsJson) If not &TFcarGruTurno_Sels.Count = 0 &i = 1 For &TFcarGruTurno_Sel in &TFcarGruTurno_Sels If &i = 1 &TFcarGruTurno_SelDscs = '' Else &TFcarGruTurno_SelDscs += ', ' EndIf &FilterTFcarGruTurno_SelValueDescription = &TFcarGruTurno_Sel.EnumerationDescription()
&TFcarGruTurno_SelDscs += &FilterTFcarGruTurno_SelValueDescription &i += 1 EndFor print printBlockTFcarGruTurno_Sel EndIf If not (&TFpratIngrQuantidade.IsEmpty() AND &TFpratIngrQuantidade_To.IsEmpty()) print printBlockTFpratIngrQuantidade &TFpratIngrQuantidade_To_Description = format('%1 (%2)', "Qtdade (percapta)", "WWP_TSTo") print printBlockTFpratIngrQuantidade_To EndIf &TFpratIngrStatus_Sels.FromJson(&TFpratIngrStatus_SelsJson) If not &TFpratIngrStatus_Sels.Count = 0 &i = 1 For &TFpratIngrStatus_Sel in &TFpratIngrStatus_Sels If &i = 1 &TFpratIngrStatus_SelDscs = '' Else &TFpratIngrStatus_SelDscs += ', ' EndIf &FilterTFpratIngrStatus_SelValueDescription = &TFpratIngrStatus_Sel.EnumerationDescription()
&TFpratIngrStatus_SelDscs += &FilterTFpratIngrStatus_SelValueDescription &i += 1 EndFor print printBlockTFpratIngrStatus_Sel EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnspratosingredientes order prefCodigo pratoCodigo AreEnsSequencial pratIngrProdCodigo when &OrderedBy = 1 AND &OrderedDsc = False order (prefCodigo) (pratoCodigo) (AreEnsSequencial) (pratIngrProdCodigo) when &OrderedBy = 1 AND &OrderedDsc = True order prefCodigo pratoCodigo AreEnsSequencial AreEnsEtapaNome when &OrderedBy = 2 AND &OrderedDsc = False order (prefCodigo) (pratoCodigo) (AreEnsSequencial) (AreEnsEtapaNome) when &OrderedBy = 2 AND &OrderedDsc = True order prefCodigo pratoCodigo AreEnsSequencial carGruTurno when &OrderedBy = 3 AND &OrderedDsc = False order (prefCodigo) (pratoCodigo) (AreEnsSequencial) (carGruTurno) when &OrderedBy = 3 AND &OrderedDsc = True order prefCodigo pratoCodigo AreEnsSequencial pratIngrQuantidade when &OrderedBy = 4 AND &OrderedDsc = False order (prefCodigo) (pratoCodigo) (AreEnsSequencial) (pratIngrQuantidade) when &OrderedBy = 4 AND &OrderedDsc = True order prefCodigo pratoCodigo AreEnsSequencial pratIngrStatus when &OrderedBy = 5 AND &OrderedDsc = False order (prefCodigo) (pratoCodigo) (AreEnsSequencial) (pratIngrStatus) when &OrderedBy = 5 AND &OrderedDsc = True
using trnspratosingredientesWWDS(&prefCodigo, &pratoCodigo, &DynamicFiltersSelector1, &DynamicFiltersOperator1, &pratIngrProdCodigo1, &AreEnsEtapaNome1 , &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &pratIngrProdCodigo2, &AreEnsEtapaNome2, &DynamicFiltersEnabled3 , &DynamicFiltersSelector3, &DynamicFiltersOperator3, &pratIngrProdCodigo3, &AreEnsEtapaNome3, &TFpratIngrProdCodigo, &TFpratIngrProdCodigo_Sel , &TFAreEnsEtapaNome, &TFAreEnsEtapaNome_Sel, &TFcarGruTurno_Sels, &TFpratIngrQuantidade, &TFpratIngrQuantidade_To, &TFpratIngrStatus_Sels) Where prefCodigo = &prefCodigo &carGruTurnoDescription = carGruTurno.EnumerationDescription() &pratIngrStatusDescription = pratIngrStatus.EnumerationDescription()
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnspratosingredientesWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnspratosingredientesWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnspratosingredientesWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFPRATINGRPRODCODIGO" &TFpratIngrProdCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRATINGRPRODCODIGO_SEL" &TFpratIngrProdCodigo_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAREENSETAPANOME" &TFAreEnsEtapaNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAREENSETAPANOME_SEL" &TFAreEnsEtapaNome_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARGRUTURNO_SEL" &TFcarGruTurno_SelsJson = &GridStateFilterValue.Value &TFcarGruTurno_Sels.FromJson(&TFcarGruTurno_SelsJson) Case &GridStateFilterValue.Name = !"TFPRATINGRQUANTIDADE" &TFpratIngrQuantidade.FromString(&GridStateFilterValue.Value) &TFpratIngrQuantidade_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPRATINGRSTATUS_SEL" &TFpratIngrStatus_SelsJson = &GridStateFilterValue.Value &TFpratIngrStatus_Sels.FromJson(&TFpratIngrStatus_SelsJson) Case &GridStateFilterValue.Name = !"PARM_&PREFCODIGO" &prefCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"PARM_&PRATOCODIGO" &pratoCodigo.FromString(&GridStateFilterValue.Value) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
